/* selecthahomeCost */
SELECT	TEXT1
FROM	ICOMCOD2
WHERE	1=1
AND		TYPE = 'C020'				
AND		FLAG = 'Y'
AND		COMPANY_CODE = #{st_buyer}
AND		CODE = #{st_code}


/* selecthahomeAccount */
SELECT	TEXT1
FROM	ICOMCOD2
WHERE	1=1
AND		TYPE = 'M014'
AND		FLAG = 'Y'
AND 	COMPANY_CODE = #{st_buyer}
AND		CODE = #{st_code}
